// Generated by `just generate` from `src/plugins/claudetto/slices/prompt/domain/variants.ts`. Edit the source and run `just generate`.
// The prompt text of design D15: the rules that every model shares, and one variant for each model.
// `prompt.compose` returns the shared sections and a variant at session start, and `session.append` adds a short block to the task row of a subagent.
// Each section reads the same for every user of a model, so it sits before the cache boundary.
// An output style reaches the model as a message and holds only role, tone, and format, so the rules are here.
// The texts come from `prompts/` of the slice through `just generate`.
// The `intro` section is the `lean_body` transform of the live block of Claude Code 2.1.301 in `live-block.ts`, which names its capture command.

import { RUN_CHECKS_BIN } from "../../../kernel/paths.ts";
import {
  ACTIONS,
  BLOCK_LINE,
  BLOCKS,
  COUNTS,
  DOING_TASKS,
  EVIDENCE_LINE,
  FABLE_NOTES,
  OPUS_NOTES,
  STEP_LINE,
  SYSTEM,
  TOOLS,
  VERIFICATION,
  VERIFY_LINE,
} from "../prompts.ts";
import { transform as leanBody } from "../transforms/lean_body.ts";
import { LIVE_LEAN_BODY } from "./live-block.ts";

/** The section with the `tag` and the `text`. */
const section = (tag: string, text: string): string =>
  `<${tag}>\n${text}\n</${tag}>`;

/**
 * The identity, the security rule, and the harness rules of the built-in `lean_body` section, in their transformed text.
 * A variant replaces `lean_body`, so without this section the model loses these rules.
 */
export const INTRO = leanBody(LIVE_LEAN_BODY).trim();

/**
 * The word for a path in a shell command: the path itself when it has only safe characters, and else in single quotes.
 * The plugin root can hold a space or a quote, for example in a home folder.
 */
export const shellWord = (path: string): string =>
  /^[\w@%+=:,./-]+$/.test(path) ? path : `'${path.replaceAll("'", "'\\''")}'`;

/**
 * The shared sections, in prompt order.
 * `root` is the root of the plugin.
 * The `tools` section names the `claudetto-run-checks` file by its path under `root`,
 * because Claude Code adds the `bin/` folder of a plugin to `PATH` only through the shell snapshot (D57).
 */
export const sharedSections = (root: string): string[] => [
  section("intro", INTRO),
  section("doing_tasks", DOING_TASKS),
  section("system", SYSTEM),
  section("blocks", BLOCKS),
  section("verification", VERIFICATION),
  section("actions", ACTIONS),
  section("tools", TOOLS({ bin: shellWord(`${root}/bin/${RUN_CHECKS_BIN}`) })),
  section("counts", COUNTS),
];

const notes = (text: string) => `<model_notes>\n${text}\n</model_notes>`;

/** The key of the variant of each model. */
export type VariantKey = "opus" | "sonnet" | "haiku" | "fable";

/**
 * The variant of each model: the model name, the section with its model lines, and the block for a subagent.
 * A subagent does not get the shared sections, so the block of each model carries the block line of design D15 and the evidence line of design D30.
 * The shared `verification` section holds the verification rule for the main session, so no variant repeats it.
 * The block of Sonnet 5.5 and Haiku 5.5 keeps the verification line, because a subagent does not get the shared sections.
 * Fable 5.1 follows its own guide, and its fit is open until the variant evals.
 */
export const VARIANTS: Record<
  VariantKey,
  { name: string; sections: string[]; block: string }
> = {
  opus: {
    name: "Opus 5.5",
    sections: [notes(OPUS_NOTES)],
    block: `${BLOCK_LINE}\n${EVIDENCE_LINE}`,
  },
  sonnet: {
    name: "Sonnet 5.5",
    sections: [],
    block: `${VERIFY_LINE}\n${BLOCK_LINE}\n${EVIDENCE_LINE}`,
  },
  haiku: {
    name: "Haiku 5.5",
    sections: [notes(STEP_LINE)],
    block: `${VERIFY_LINE}\n${STEP_LINE}\n${BLOCK_LINE}\n${EVIDENCE_LINE}`,
  },
  fable: {
    name: "Fable 5.1",
    sections: [notes(FABLE_NOTES)],
    block: `${BLOCK_LINE}\n${EVIDENCE_LINE}`,
  },
};

/**
 * The shared sections and the sections of a variant, as `prompt.compose` takes them: `claudetto:<tag>` ids, all shared.
 */
export const variantSections = (
  key: VariantKey,
  root: string,
): { id: string; text: string; scope: "shared" }[] =>
  [...sharedSections(root), ...VARIANTS[key].sections].map((text) => ({
    id: `claudetto:${/^<(\w+)>/.exec(text)?.[1]}`,
    text,
    scope: "shared" as const,
  }));

/** The first line of the block that `session.append` adds. A task prompt that has it gets no second block. */
export const BLOCK_OPEN = "<claudetto_model_notes>";

/** The block that ends the task prompt of a subagent on a model. */
export const spawnBlock = (key: VariantKey): string =>
  `${BLOCK_OPEN}\n${VARIANTS[key].block}\n</claudetto_model_notes>`;
